:root{
  --bg:#080d17;
  --bg-day:#163a64;
  --elev:rgba(18,28,48,.68);
  --elev2:rgba(255,255,255,.14);
  --border:rgba(255,255,255,.18);
  --text:#e9eefb;
  --dim:#8494b3;
  --dim2:#5c6d8c;
  --cool:#35d0c4;
  --storm:#f5a524;
  --severe:#ef4b5f;
  --cape:#a78bfa;
  --good:#4ade80;
  --radius:18px;
  --glass-alpha:.14;
  --glass-blur:24px;
  --glass-shadow:0 18px 55px rgba(0,0,0,.18);
  --accent:var(--cool);
  --warn-color:var(--good);
  --card-gap:12px;
  --anim-speed:1;
}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent;}
html,body{
  width:100%;
  min-height:100%;
  margin:0;
  padding:0;
  background:#0b172b;
  overflow-x:hidden;
}
html{min-height:-webkit-fill-available;}
body{
  font-family:'Inter',system-ui,sans-serif;
  background:#0b172b;
  color:var(--text);
  min-height:100vh;
  min-height:100dvh;
  min-height:-webkit-fill-available;
  display:flex;
  flex-direction:column;
  overflow-y:auto;
  -webkit-overflow-scrolling:touch;
  touch-action:pan-y pinch-zoom;
  text-rendering:optimizeLegibility;
}
::-webkit-scrollbar{width:6px;height:6px;}
::-webkit-scrollbar-thumb{background:var(--elev2);border-radius:6px;}
h1,h2,h3,.display{font-family:'Space Grotesk',sans-serif;}
.mono{font-family:'JetBrains Mono',monospace;}
button{font-family:inherit;}
a{color:inherit;}

/* ---------- Branded startup splash ---------- */
.app-splash{
  position:fixed;
  inset:0;
  width:100%;
  height:100vh;
  height:100dvh;
  z-index:5000;
  display:grid;
  place-items:center;
  background:
    radial-gradient(circle at 50% 35%, rgba(47,147,255,.22), transparent 42%),
    linear-gradient(180deg,#102d59 0%,#081a35 55%,#050f20 100%);
  transition:opacity 420ms ease, visibility 420ms ease;
}
.app-splash.is-hidden{
  opacity:0;
  visibility:hidden;
  pointer-events:none;
}
.app-splash-content{
  display:grid;
  justify-items:center;
  gap:14px;
  padding:calc(env(safe-area-inset-top) + 24px) 24px calc(env(safe-area-inset-bottom) + 24px);
}
.app-splash-logo-wrap{
  position:relative;
  overflow:hidden;
  border-radius:28%;
  box-shadow:0 26px 70px rgba(0,0,0,.26);
}
.app-splash-logo-wrap::after{
  content:"";
  position:absolute;
  inset:-20%;
  background:linear-gradient(105deg,transparent 20%,rgba(255,255,255,.34) 48%,transparent 72%);
  transform:translateX(-120%);
  animation:splashSheen 900ms ease 320ms both;
  pointer-events:none;
}
.app-splash-logo{
  width:clamp(112px,29vw,168px);
  height:auto;
  display:block;
  animation:splashLogoEnter 720ms cubic-bezier(.2,.8,.2,1) both;
}
.app-splash-name{
  font-family:'Space Grotesk',sans-serif;
  font-size:clamp(28px,7vw,42px);
  font-weight:800;
  letter-spacing:.02em;
  opacity:0;
  animation:splashTextIn 520ms ease 260ms forwards;
}
.app-splash-status{
  color:rgba(235,244,255,.72);
  font-size:14px;
  opacity:0;
  animation:splashTextIn 520ms ease 360ms forwards;
}
.app-splash-progress{
  width:min(210px,54vw);
  height:3px;
  border-radius:999px;
  overflow:hidden;
  background:rgba(255,255,255,.14);
  margin-top:4px;
}
.app-splash-progress span{
  display:block;
  width:45%;
  height:100%;
  border-radius:inherit;
  background:linear-gradient(90deg,rgba(101,216,255,.25),#70d9ff,rgba(101,216,255,.25));
  animation:splashProgress 1.25s ease-in-out infinite;
}
@keyframes splashLogoEnter{
  from{opacity:0;transform:scale(.92) translateY(8px);}
  to{opacity:1;transform:scale(1) translateY(0);}
}
@keyframes splashTextIn{
  to{opacity:1;}
}
@keyframes splashProgress{
  from{transform:translateX(-110%);}
  to{transform:translateX(230%);}
}
@keyframes splashSheen{
  to{transform:translateX(120%);}
}

/* ---------- App shell ---------- */
#app{
  flex:1;
  display:flex;
  flex-direction:column;
  width:100%;
  min-height:100vh;
  min-height:100dvh;
  min-height:-webkit-fill-available;
  position:relative;
  z-index:1;
  background:transparent;
}
.screen{
  flex:1;
  min-height:100vh;
  min-height:100dvh;
  min-height:-webkit-fill-available;
  overflow-y:visible;
  overflow-x:hidden;
  overscroll-behavior-y:auto;
  touch-action:pan-y pinch-zoom;
  display:none;
  -webkit-overflow-scrolling:touch;
}
.screen.active{display:block;}
.screen-inner{max-width:640px;margin:0 auto;padding:14px 14px 100px;}
#home .screen-inner{max-width:860px;padding:10px clamp(14px,5vw,44px) 104px;}

/* ---------- Animated weather background ---------- */
#weatherBG{
  position:fixed;inset:0;z-index:0;overflow:hidden;pointer-events:none;
  width:100%;
  height:100vh;
  height:100dvh;
  min-height:-webkit-fill-available;
  transition:background 1.2s ease;
}
.wbg-sky{
  position:absolute;inset:0;transition:background 1.4s ease, opacity 1.2s ease;
  background:
    radial-gradient(circle at 18% 8%, rgba(255,232,181,.95) 0%, rgba(255,232,181,.24) 22%, transparent 44%),
    radial-gradient(circle at 78% 18%, rgba(98,202,255,.42) 0%, transparent 38%),
    linear-gradient(165deg, #69aef7 0%, #3386dc 32%, #1e5fa7 58%, #112b55 82%, #07111f 100%);
}
#weatherBG::after{
  content:"";position:absolute;inset:0;
  background:linear-gradient(180deg, rgba(255,255,255,.05), transparent 24%, rgba(0,0,0,.18) 100%);
}
#weatherBG.night .wbg-sky{background:radial-gradient(circle at 52% 14%, rgba(126,160,225,.18), transparent 24%),linear-gradient(165deg,#1c2e55 0%,#111d3a 42%,#080d17 78%);}
#weatherBG.cloudy .wbg-sky{background:radial-gradient(circle at 22% 6%, rgba(210,225,244,.3), transparent 28%),linear-gradient(165deg,#607b9f 0%,#344b6f 44%,#0a1324 86%);}
#weatherBG.rainy .wbg-sky{background:radial-gradient(circle at 18% 0%, rgba(157,189,225,.22), transparent 30%),linear-gradient(165deg,#415d7f 0%,#263a58 45%,#09111f 86%);}
#weatherBG.stormy .wbg-sky{background:radial-gradient(circle at 78% 6%, rgba(169,121,255,.22), transparent 28%),linear-gradient(165deg,#33234d 0%,#211b35 46%,#070b16 86%);}
#weatherBG.snowy .wbg-sky{background:radial-gradient(circle at 20% 4%, rgba(235,246,255,.34), transparent 30%),linear-gradient(165deg,#6a87ad 0%,#3c5579 45%,#10192b 86%);}

.wbg-stars{position:absolute;inset:0;opacity:0;transition:opacity 1.2s ease;
  background-image:radial-gradient(1.5px 1.5px at 20% 20%, #fff, transparent),
    radial-gradient(1.5px 1.5px at 70% 15%, #fff, transparent),
    radial-gradient(1px 1px at 45% 30%, #fff, transparent),
    radial-gradient(1px 1px at 85% 40%, #fff, transparent),
    radial-gradient(1.5px 1.5px at 30% 45%, #fff, transparent),
    radial-gradient(1px 1px at 60% 8%, #fff, transparent);
  background-repeat:no-repeat;
}
#weatherBG.night .wbg-stars{opacity:.5;}

.wbg-sun{
  position:absolute;top:-6%;left:-8%;width:340px;height:340px;border-radius:50%;
  background:radial-gradient(circle, #ffffff 0%, #fff6d9 18%, #ffe9a8 32%, rgba(255,233,168,.35) 55%, rgba(255,233,168,0) 72%);
  opacity:0;transition:opacity 1s ease, transform 1s ease;
  box-shadow:0 0 140px 60px rgba(255,236,180,.18);
  animation:sunpulse 6s ease-in-out infinite;
}
#weatherBG.sunny .wbg-sun{opacity:1;}
#weatherBG.cloudy:not(.night) .wbg-sun{opacity:.48;}
@keyframes sunpulse{0%,100%{transform:scale(1);}50%{transform:scale(1.04);}}

.wbg-moon{
  position:absolute;top:7%;left:50%;width:70px;height:70px;margin-left:-35px;border-radius:50%;
  background:radial-gradient(circle at 35% 35%, #eef2fb 0%, #c9d3ea 55%, rgba(201,211,234,0) 75%);
  opacity:0;transition:opacity 1s ease;box-shadow:0 0 50px 12px rgba(201,211,234,.15);
}
#weatherBG.night.sunny .wbg-moon{opacity:.9;}
#weatherBG.night.cloudy .wbg-moon{opacity:.38;}
#weatherBG.night.sunny .wbg-sun{opacity:0;}

.wbg-clouds{position:absolute;inset:0;opacity:0;transition:opacity 1.2s ease;}
.wbg-clouds .cloud{
  position:absolute;width:260px;height:96px;border-radius:999px;
  background:
    radial-gradient(circle at 20% 58%, rgba(255,255,255,.88) 0 23%, transparent 24%),
    radial-gradient(circle at 36% 39%, rgba(255,255,255,.95) 0 30%, transparent 31%),
    radial-gradient(circle at 54% 32%, rgba(246,250,255,.92) 0 34%, transparent 35%),
    radial-gradient(circle at 72% 53%, rgba(237,244,255,.84) 0 27%, transparent 28%),
    linear-gradient(180deg, rgba(255,255,255,.82), rgba(190,207,232,.42) 72%, rgba(130,153,190,.18));
  box-shadow:0 18px 26px rgba(5,12,28,.10);
  opacity:.72;
  transform:translate3d(0,0,0);
  animation-play-state:paused;
  mix-blend-mode:screen;
}
.wbg-clouds .cloud::before,.wbg-clouds .cloud::after{
  content:"";position:absolute;inset:20% 8% 6%;border-radius:999px;
  background:linear-gradient(180deg,rgba(255,255,255,.55),rgba(210,225,245,.18));
  opacity:.52;
}
.wbg-clouds .cloud::after{inset:55% 12% 0;background:rgba(77,101,140,.14);opacity:.42;}
.cloud.c1{width:370px;height:138px;top:5%;left:-16%;animation:drift 82s linear infinite;}
.cloud.c2{width:300px;height:112px;top:13%;left:24%;animation:drift 110s linear infinite reverse;opacity:.62;transform:scale(.92);}
.cloud.c3{width:430px;height:154px;top:1%;left:58%;animation:drift 98s linear infinite;opacity:.66;}
.cloud.c4{width:230px;height:88px;top:22%;left:74%;animation:drift 72s linear infinite reverse;opacity:.56;}
.cloud.c5{width:520px;height:170px;top:30%;left:-20%;animation:driftSlow 128s linear infinite;opacity:0;}
.cloud.c6{width:460px;height:150px;top:39%;left:34%;animation:driftSlow 145s linear infinite reverse;opacity:0;}
.cloud.c7{width:620px;height:190px;top:54%;left:52%;animation:driftSlow 165s linear infinite;opacity:0;}
.cloud.c8{width:340px;height:120px;top:68%;left:8%;animation:driftSlow 118s linear infinite reverse;opacity:0;}
@keyframes drift{from{transform:translate3d(-12vw,0,0);}to{transform:translate3d(112vw,0,0);}}
@keyframes driftSlow{from{transform:translate3d(-18vw,0,0);}to{transform:translate3d(118vw,0,0);}}
#weatherBG.cloudy .wbg-clouds,#weatherBG.rainy .wbg-clouds,#weatherBG.stormy .wbg-clouds,#weatherBG.snowy .wbg-clouds{opacity:1;}
#weatherBG.cloudy .cloud.c1,#weatherBG.cloudy .cloud.c2,#weatherBG.cloudy .cloud.c3,#weatherBG.cloudy .cloud.c4,
#weatherBG.rainy .cloud.c1,#weatherBG.rainy .cloud.c2,#weatherBG.rainy .cloud.c3,#weatherBG.rainy .cloud.c4,
#weatherBG.stormy .cloud.c1,#weatherBG.stormy .cloud.c2,#weatherBG.stormy .cloud.c3,#weatherBG.stormy .cloud.c4,
#weatherBG.snowy .cloud.c1,#weatherBG.snowy .cloud.c2,#weatherBG.snowy .cloud.c3,#weatherBG.snowy .cloud.c4{animation-play-state:running;}
#weatherBG.cloudy.cloud-cover-heavy .cloud.c5,
#weatherBG.cloudy.cloud-cover-heavy .cloud.c6,
#weatherBG.cloudy.cloud-cover-heavy .cloud.c7,
#weatherBG.cloudy.cloud-cover-heavy .cloud.c8,
#weatherBG.rainy .cloud.c5,
#weatherBG.rainy .cloud.c6,
#weatherBG.stormy .cloud.c5,
#weatherBG.stormy .cloud.c6,
#weatherBG.snowy .cloud.c5,
#weatherBG.snowy .cloud.c6{opacity:.52;}
#weatherBG.cloudy.cloud-cover-heavy .cloud.c5,
#weatherBG.cloudy.cloud-cover-heavy .cloud.c6,
#weatherBG.cloudy.cloud-cover-heavy .cloud.c7,
#weatherBG.cloudy.cloud-cover-heavy .cloud.c8,
#weatherBG.rainy .cloud.c5,
#weatherBG.rainy .cloud.c6,
#weatherBG.stormy .cloud.c5,
#weatherBG.stormy .cloud.c6,
#weatherBG.snowy .cloud.c5,
#weatherBG.snowy .cloud.c6{animation-play-state:running;}
#weatherBG.cloudy.cloud-cover-heavy .wbg-sun{opacity:.18;}
#weatherBG.night.cloudy.cloud-cover-heavy .wbg-moon{opacity:.18;}
#weatherBG.cloudy.cloud-cover-light .cloud.c1,
#weatherBG.cloudy.cloud-cover-light .cloud.c2,
#weatherBG.cloudy.cloud-cover-light .cloud.c3,
#weatherBG.cloudy.cloud-cover-light .cloud.c4{opacity:.42;}


.wbg-rain{
  position:absolute;inset:-25% 0 0 0;opacity:0;transition:opacity .8s ease;
  background-image:
    radial-gradient(ellipse at 14% 0%, rgba(216,236,255,.75) 0 1.5px, transparent 2.6px),
    radial-gradient(ellipse at 58% 0%, rgba(216,236,255,.70) 0 1.7px, transparent 2.8px),
    repeating-linear-gradient(108deg, rgba(183,217,255,.20) 0 1px, transparent 1px 21px);
  background-size:120px 150px,140px 170px,100% 180px;
  animation:rainfall .9s linear infinite;
  animation-play-state:paused;
  will-change:background-position,opacity;
}
.wbg-rain::before,.wbg-rain::after{
  content:"";position:absolute;inset:0;opacity:.8;
  background-image:
    radial-gradient(ellipse at 24% 0%, rgba(235,246,255,.84) 0 1.6px, transparent 2.8px),
    radial-gradient(ellipse at 66% 0%, rgba(235,246,255,.62) 0 1.5px, transparent 2.6px),
    repeating-linear-gradient(108deg, rgba(201,229,255,.14) 0 1px, transparent 1px 28px);
  background-size:150px 210px,190px 180px,100% 210px;
  animation:rainfall 1.25s linear infinite;
  animation-play-state:inherit;
}
.wbg-rain::after{display:none;}
#weatherBG.stormy .wbg-rain{filter:brightness(1.2);}
#weatherBG.stormy .wbg-rain::before{opacity:1;}
#weatherBG.stormy .wbg-rain::after{opacity:.72;}
@keyframes rainfall{from{background-position:0 -240px,0 -180px,0 -170px;}to{background-position:-82px 150px,-94px 170px,-70px 180px;}}
#weatherBG.rainy .wbg-rain,#weatherBG.stormy .wbg-rain{opacity:1;animation-play-state:running;}

.wbg-snow{
  position:absolute;inset:0;opacity:0;transition:opacity .8s ease;
  background-image:radial-gradient(2px 2px at 10% 0%, #fff, transparent),
    radial-gradient(1.5px 1.5px at 35% 0%, #fff, transparent),
    radial-gradient(2px 2px at 60% 0%, #fff, transparent),
    radial-gradient(1.5px 1.5px at 80% 0%, #fff, transparent),
    radial-gradient(2px 2px at 95% 0%, #fff, transparent);
  background-repeat:repeat-y;background-size:100% 90px;
  animation:snowfall 4.5s linear infinite;
}
#weatherBG.snowy .wbg-snow{opacity:.85;}
@keyframes snowfall{from{background-position:0 -90px;}to{background-position:0 500px;}}

.wbg-lightning{
  position:absolute;inset:0;opacity:0;transition:opacity .35s ease-in;
  background:
    radial-gradient(circle at 62% 8%, rgba(235,244,255,.46), transparent 22%),
    linear-gradient(180deg,rgba(217,232,255,.28),rgba(255,255,255,0) 54%);
}
.wbg-lightning::before{
  content:"";position:absolute;top:-2%;left:55%;width:96px;height:58vh;
  background:linear-gradient(180deg,#fff 0%,#dceaff 38%,rgba(133,186,255,.75) 72%,transparent 100%);
  clip-path:polygon(44% 0,64% 0,49% 29%,69% 29%,35% 100%,45% 48%,27% 48%);
  filter:drop-shadow(0 0 10px rgba(255,255,255,.95)) drop-shadow(0 0 32px rgba(117,180,255,.9));
  opacity:0;
}
.wbg-lightning::after{
  content:"";position:absolute;inset:0;background:rgba(235,244,255,.34);opacity:0;
}
#weatherBG.stormy .wbg-lightning.flash{opacity:1;transition:opacity .045s ease-out;}
#weatherBG.stormy .wbg-lightning.flash::before{opacity:.95;}
#weatherBG.stormy .wbg-lightning.flash::after{opacity:1;animation:stormFlash .22s ease-out forwards;}
@keyframes stormFlash{0%{opacity:.9;}45%{opacity:.22;}100%{opacity:0;}}


/* ---------- Top bar / search ---------- */
.topbar{
  padding:10px 14px 6px;
  max-width:860px;margin:0 auto;width:100%;
  position:sticky;top:0;z-index:5;
}
.searchwrap{position:relative;}
.searchbox{
  display:flex;align-items:center;gap:8px;
  background:rgba(255,255,255,.13);
  border:1px solid rgba(255,255,255,.22);
  border-radius:16px;
  padding:10px 14px;
  backdrop-filter:blur(24px) saturate(155%);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.18), 0 16px 45px rgba(0,0,0,.18);
}
.searchbox input{
  flex:1;background:transparent;border:none;outline:none;
  color:var(--text);font-size:15px;font-family:'Inter',sans-serif;
}
.searchbox input::placeholder{color:var(--dim2);}
.searchbox svg{flex-shrink:0;color:var(--dim);}
.searchbox .clearbtn{cursor:pointer;color:var(--dim);display:none;}
.suggestions{
  position:absolute;top:calc(100% + 6px);left:0;right:0;
  background:var(--elev);border:1px solid var(--border);
  border-radius:14px;overflow:hidden;z-index:20;
  box-shadow:0 20px 50px rgba(0,0,0,.5);
  display:none;
}
.suggestions.show{display:block;}
.sugg-item{
  padding:12px 14px;display:flex;justify-content:space-between;align-items:center;
  cursor:pointer;border-bottom:1px solid var(--border);gap:10px;
}
.sugg-item:last-child{border-bottom:none;}
.sugg-item:hover,.sugg-item:active{background:var(--elev2);}
.sugg-name{font-weight:600;font-size:14.5px;}
.sugg-sub{color:var(--dim);font-size:12.5px;text-align:right;}
.sugg-empty{padding:14px;color:var(--dim);font-size:13.5px;}
.sugg-location{
  justify-content:flex-start;
  background:linear-gradient(180deg,rgba(105,231,255,.14),rgba(255,255,255,.06));
}
.sugg-location-icon{
  width:34px;height:34px;border-radius:50%;
  display:grid;place-items:center;flex:0 0 auto;
  color:#081426;background:var(--accent);
  box-shadow:0 8px 22px rgba(53,208,196,.24);
}
.sugg-location-icon svg{width:18px;height:18px;}
.sugg-main{display:flex;flex-direction:column;gap:2px;min-width:0;}
.sugg-main .sugg-sub{text-align:left;}

/* ---------- Home hero ---------- */
.hero{text-align:center;padding:18px 0 22px;}
.hero .locname{font-size:20px;font-weight:600;display:flex;align-items:center;justify-content:center;gap:6px;}
.hero .locname .pin{width:15px;height:15px;color:var(--dim);}
.hero .bignum{font-size:98px;font-weight:600;line-height:1;margin:2px 0 0;letter-spacing:0;text-shadow:0 16px 44px rgba(0,0,0,.22);}
.hero .cond{font-size:17px;color:var(--dim);margin-top:2px;}
.hero .hilo{font-size:15px;color:var(--dim);margin-top:6px;}
.hero .hilo b{color:var(--text);font-weight:600;}
.hero .nowcast{font-size:13.5px;color:var(--cool);margin-top:8px;font-weight:600;}
.hero .updated{font-size:11px;color:var(--dim2);margin-top:6px;}

.scopebadge{
  position:absolute;top:14px;right:14px;
  display:flex;align-items:center;gap:6px;
  background:rgba(255,255,255,.06);border:1px solid var(--border);
  padding:6px 10px 6px 8px;border-radius:100px;font-size:11.5px;color:var(--dim);
  cursor:pointer;
}

/* ---------- Cards ---------- */
.card{
  background:linear-gradient(180deg,rgba(255,255,255,calc(var(--glass-alpha) + .04)),rgba(255,255,255,.08));
  backdrop-filter:blur(var(--glass-blur)) saturate(150%);
  border:1px solid rgba(255,255,255,.2);
  border-radius:var(--radius);
  padding:14px 16px;
  margin-bottom:12px;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.18), var(--glass-shadow);
}
.card-title{
  font-size:12px;text-transform:uppercase;letter-spacing:.06em;color:rgba(233,238,251,.75);
  display:flex;align-items:center;gap:6px;margin-bottom:10px;font-weight:600;
}
.card-title svg{width:13px;height:13px;}

.alert-card{
  position:relative;
  overflow:hidden;
  border-color:rgba(255,255,255,.24);
}
.alert-card::before{
  content:"";position:absolute;inset:0 auto 0 0;width:5px;background:var(--good);
}
.alert-card.yellow::before{background:#facc15;}
.alert-card.orange::before{background:#fb923c;}
.alert-card.red::before{background:#ef4444;}
.alert-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;}
.alert-code{font-size:22px;font-weight:700;font-family:'Space Grotesk',sans-serif;margin-top:-4px;}
.alert-pill{
  flex:0 0 auto;font-size:10.5px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;
  color:rgba(233,238,251,.78);border:1px solid rgba(255,255,255,.18);border-radius:999px;padding:5px 8px;
  background:rgba(255,255,255,.08);
}
.alert-title{font-size:14px;font-weight:700;margin-top:8px;}
.alert-text{font-size:13px;color:rgba(233,238,251,.78);line-height:1.45;margin-top:4px;}
.alert-source{font-size:10.5px;color:rgba(233,238,251,.54);margin-top:8px;}

.hourly-scroll{display:flex;gap:0;overflow-x:auto;margin:0 -4px;padding:0 4px;}
.hour-item{
  flex:0 0 auto;width:92px;text-align:center;padding:8px 0;
  display:flex;flex-direction:column;align-items:center;gap:6px;
}
.hour-item .t{font-size:clamp(15px,2.5vw,20px);color:rgba(233,238,251,.82);font-weight:600;}
.hour-item .icon{width:34px;height:34px;}
.hour-item .pop{font-size:14px;color:#71e8ff;height:17px;font-weight:700;}
.hour-item .v{font-size:clamp(20px,3.5vw,27px);font-weight:600;}
.hour-item.now .t{color:var(--text);font-weight:600;}


.daily-row{
  display:flex;align-items:center;gap:14px;padding:13px 0;
  border-bottom:1px solid rgba(255,255,255,.12);font-size:14px;
}
.daily-row:last-child{border-bottom:none;}
.daily-card{border-radius:26px;padding:18px 24px;}
.daily-row .dname{width:112px;font-size:clamp(20px,3.4vw,27px);font-weight:500;}
.daily-row .dname.today{color:#fff;}
.daily-row .dicon{width:34px;height:34px;flex-shrink:0;}
.daily-row .dpop{width:38px;font-size:15px;color:#71e8ff;text-align:right;font-weight:700;}
.daily-row .dlow{width:46px;text-align:right;color:rgba(233,238,251,.58);font-size:clamp(20px,3.2vw,28px);}
.bar-track{flex:1;height:7px;background:rgba(3,26,62,.38);border-radius:999px;position:relative;margin:0 6px;min-width:84px;}
.bar-fill{position:absolute;top:0;height:7px;border-radius:999px;background:linear-gradient(90deg,#34d66a,#f4e83d,#ff9f25);}
.daily-row .dhigh{width:48px;font-size:clamp(22px,3.4vw,30px);font-weight:500;text-align:right;}

.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;}
.detail-card{
  background:linear-gradient(180deg,rgba(255,255,255,.16),rgba(255,255,255,.075));backdrop-filter:blur(28px) saturate(150%);border:1px solid rgba(255,255,255,.2);
  border-radius:var(--radius);padding:13px 15px;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.16), 0 14px 42px rgba(0,0,0,.14);
}
.detail-card.wide{grid-column:span 2;}
.detail-card .dt-title{font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:rgba(233,238,251,.75);display:flex;align-items:center;gap:5px;font-weight:600;}
.detail-card .dt-title svg{width:12px;height:12px;}
.detail-card .dt-val{font-size:26px;font-weight:600;margin-top:6px;font-family:'Space Grotesk',sans-serif;}
.detail-card .dt-sub{font-size:12px;color:rgba(233,238,251,.75);margin-top:2px;}

/* ---- wind compass ---- */
.compass-row{display:flex;align-items:center;justify-content:space-between;margin-top:4px;}
.compass{position:relative;width:78px;height:78px;border-radius:50%;border:2px solid rgba(255,255,255,.18);flex-shrink:0;}
.compass .cdir{position:absolute;font-size:10px;font-weight:700;color:rgba(233,238,251,.6);}
.compass .cdir.n{top:3px;left:50%;transform:translateX(-50%);}
.compass .cdir.z{bottom:3px;left:50%;transform:translateX(-50%);}
.compass .cdir.o{right:4px;top:50%;transform:translateY(-50%);}
.compass .cdir.w{left:4px;top:50%;transform:translateY(-50%);}
.compass .needle{
  position:absolute;left:50%;top:50%;width:2.5px;height:30px;background:linear-gradient(0deg,transparent,var(--cool));
  transform-origin:50% 100%;border-radius:2px;
}
.compass .chub{position:absolute;left:50%;top:50%;width:6px;height:6px;margin:-3px 0 0 -3px;border-radius:50%;background:var(--text);}

/* ---- pressure gauge ---- */
.gauge-row{display:flex;align-items:center;gap:14px;margin-top:4px;}
.semigauge{width:100px;flex-shrink:0;}
.gauge-labels{display:flex;justify-content:space-between;font-size:10.5px;color:rgba(233,238,251,.6);margin-top:2px;padding:0 2px;}

/* ---- uv bar ---- */
.uvbar{position:relative;height:6px;border-radius:4px;margin-top:10px;
  background:linear-gradient(90deg,#4ade80,#e8d64a,#f0913c,#e8503c,#b13cd6);}
.uvdot{position:absolute;top:50%;width:11px;height:11px;border-radius:50%;background:#fff;border:2px solid #222;
  transform:translate(-50%,-50%);box-shadow:0 0 4px rgba(0,0,0,.4);}

/* ---- sun arc ---- */
.sunarc{margin-top:2px;}
.sunarc svg{width:100%;height:auto;display:block;}
.sunarc-labels{display:flex;justify-content:space-between;font-size:13px;font-weight:600;margin-top:-6px;}

/* ---- moon card ---- */
.moon-row{display:flex;align-items:center;gap:16px;margin-top:4px;}
.moonvisual{
  width:56px;height:56px;border-radius:50%;flex-shrink:0;position:relative;overflow:hidden;
  background:radial-gradient(circle at 35% 35%, #eef2fb 0%, #c9d3ea 60%, #96a4c4 100%);
}
.moonshadow{position:absolute;inset:0;background:rgba(8,13,23,.82);border-radius:50%;}
.moonline{display:flex;justify-content:space-between;font-size:13px;padding:3px 0;}
.moonline span{color:rgba(233,238,251,.7);}


/* ---------- Expanded app sections ---------- */
.section-nav{position:sticky;top:58px;z-index:4;display:flex;gap:8px;overflow-x:auto;margin:0 0 12px;padding:8px 0;scrollbar-width:none;}
.section-nav::-webkit-scrollbar{display:none;}
.section-nav a{flex:0 0 auto;text-decoration:none;color:rgba(233,238,251,.82);font-size:12px;font-weight:700;padding:8px 11px;border-radius:999px;border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.08);backdrop-filter:blur(18px);}
.section-nav a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:2px;}
.app-section{scroll-margin-top:110px;}
.smart-list{display:grid;gap:8px;margin-bottom:12px;}
.smart-item{padding:10px 12px;border-radius:14px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.12);font-size:13px;line-height:1.35;}
.notify-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:10px 0 8px;}
.notify-grid label{font-size:12px;color:rgba(233,238,251,.8);display:flex;align-items:center;gap:6px;}
.map-tabs{display:flex;gap:7px;overflow-x:auto;margin-bottom:10px;}
.map-tabs button{flex:0 0 auto;border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.08);color:var(--dim);border-radius:999px;padding:7px 10px;font-size:12px;font-weight:700;}
.map-tabs button.active{background:var(--accent);color:#04302c;border-color:var(--accent);}
.map-preview{position:relative;height:180px;border-radius:16px;border:1px solid rgba(255,255,255,.14);background:linear-gradient(135deg,rgba(20,75,145,.4),rgba(20,30,60,.28));overflow:hidden;}
.home-weather-map{position:absolute;inset:0;width:100%;height:100%;background:#10233f;}
.map-preview-status{
  position:absolute;left:10px;right:10px;bottom:10px;z-index:5;
  border-radius:999px;border:1px solid rgba(255,255,255,.20);
  background:rgba(8,16,32,.72);color:rgba(245,249,255,.88);
  backdrop-filter:blur(16px) saturate(150%);
  -webkit-backdrop-filter:blur(16px) saturate(150%);
  padding:8px 10px;font-size:12px;font-weight:700;text-align:center;
}
.map-preview-status.hidden{display:none;}
.legend-row{display:flex;align-items:center;gap:8px;margin-top:10px;font-size:11px;color:var(--dim);}
.legend-row i{height:6px;flex:1;border-radius:999px;background:linear-gradient(90deg,#3d7ff0,#35c7e0,#3fd07a,#e8d64a,#f0913c,#e8503c,#b13cd6);}
.chart-grid{display:grid;grid-template-columns:1fr;gap:12px;}
.mini-chart{border-radius:16px;border:1px solid rgba(255,255,255,.12);background:linear-gradient(180deg,rgba(255,255,255,.085),rgba(255,255,255,.045));padding:12px;min-width:0;box-shadow:inset 0 1px 0 rgba(255,255,255,.08);}
.mini-chart-head{display:flex;justify-content:space-between;gap:10px;font-size:13px;color:rgba(233,238,251,.86);margin-bottom:7px;}
.mini-chart-head span{color:var(--dim);}
.chart-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px;margin:8px 0 7px;}
.chart-stats span{min-width:0;border-radius:10px;background:rgba(255,255,255,.065);border:1px solid rgba(255,255,255,.09);padding:6px 7px;font-size:10.5px;color:rgba(233,238,251,.66);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.chart-stats b{display:block;margin-top:1px;font-size:15px;color:var(--text);line-height:1.05;}
.mini-chart svg{width:100%;height:170px;display:block;overflow:visible;}
.mini-chart .gridline{stroke:rgba(255,255,255,.14);stroke-width:.35;vector-effect:non-scaling-stroke;}
.mini-chart text{font-family:'Inter',sans-serif;fill:rgba(233,238,251,.62);font-size:3.15px;font-weight:600;}
.mini-chart .ylabel{text-anchor:start;}
.mini-chart .xlabel{text-anchor:middle;}
.mini-chart .line{fill:none;stroke-width:2.45;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:180;stroke-dashoffset:180;animation:drawline calc(1.1s * var(--anim-speed)) ease forwards;vector-effect:non-scaling-stroke;}
.mini-chart .main{stroke:var(--accent);}.mini-chart .sub{stroke:rgba(245,165,36,.95);stroke-width:1.9;}
.mini-chart .point{stroke:rgba(4,10,22,.72);stroke-width:.65;filter:drop-shadow(0 1px 2px rgba(0,0,0,.35));}
.mini-chart .point.max{fill:#f5a524;}.mini-chart .point.min{fill:#35d0c4;}
.mini-chart .hit{fill:transparent;stroke:transparent;pointer-events:all;}
.chart-legend{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:8px;font-size:11.5px;color:rgba(233,238,251,.72);}
.chart-legend span{display:inline-flex;align-items:center;gap:5px;}
.chart-legend i{width:18px;height:3px;border-radius:999px;display:inline-block;}
.chart-legend i.main{background:var(--accent);}.chart-legend i.sub{background:rgba(245,165,36,.95);}
@keyframes drawline{to{stroke-dashoffset:0;}}
@media (max-width: 520px){
  .chart-stats{grid-template-columns:repeat(2,minmax(0,1fr));}
  .mini-chart svg{height:150px;}
  .chart-legend{font-size:11px;gap:9px;}
}
@media (max-width: 640px){
  #home .screen-inner{padding:6px 14px 96px;}
  .hour-item{width:86px;}
  .daily-card{padding:17px 22px;}
  .daily-row{gap:10px;}
  .daily-row .dname{width:92px;}
  .daily-row .dpop{width:30px;font-size:13px;}
}
@media (max-width: 430px){
  .daily-row .dname{width:76px;font-size:19px;}
  .daily-row .dicon{width:28px;height:28px;}
  .daily-row .dlow,.daily-row .dhigh{width:36px;font-size:21px;}
  .bar-track{min-width:58px;margin:0 3px;}
}

/* Compact home restore: keep the app fast and close to the earlier layout. */
