/* ---------- Weather mood background: light, condition-aware ---------- */
#weatherBG .wbg-sun{display:block!important;}
#weatherBG .wbg-clouds,
#weatherBG .wbg-rain,
#weatherBG .wbg-snow,
#weatherBG .wbg-lightning,
#weatherBG .wbg-moon{display:none!important;}
#weatherBG.sunny:not(.night) .wbg-sky{
  background:
    radial-gradient(circle at 17% 8%, rgba(255,239,188,.88) 0%, rgba(255,218,123,.34) 18%, transparent 39%),
    radial-gradient(circle at 78% 20%, rgba(110,205,255,.34) 0%, transparent 36%),
    linear-gradient(165deg,#66b9ff 0%,#2f83da 45%,#14549a 78%,#09264e 100%)!important;
}
#weatherBG.cloudy:not(.night) .wbg-sky{
