/* ---------- Tabbar (Liquid Glass) ---------- */
:root{ --tabbar-h: 76px; }
.tabbar{
  position:absolute;left:14px;right:14px;bottom:calc(10px + env(safe-area-inset-bottom));z-index:500;
  display:flex;background:rgba(255,255,255,.14);backdrop-filter:blur(28px) saturate(180%);-webkit-backdrop-filter:blur(28px) saturate(180%);
  border:1px solid rgba(255,255,255,.28);border-radius:26px;padding:8px 10px;
  box-shadow:0 12px 34px rgba(0,0,0,.35), inset 0 1px 0 rgba(255,255,255,.35);
}
.tabbar::before{
  content:'';position:absolute;inset:0;border-radius:26px;pointer-events:none;
  background:linear-gradient(180deg, rgba(255,255,255,.22) 0%, rgba(255,255,255,0) 40%);
}
.tabbtn{
  flex:1;display:flex;flex-direction:column;align-items:center;gap:2px;position:relative;z-index:1;
  background:none;border:none;color:rgba(233,238,251,.65);padding:7px 0;cursor:pointer;font-size:10.5px;
  font-weight:600;letter-spacing:.02em;transition:color .2s ease;
}
.tabbtn svg{width:21px;height:21px;}
.tabbtn.active{color:#fff;}
.tabbtn.active::before{
  content:'';position:absolute;inset:-2px 6px;background:rgba(255,255,255,.18);border-radius:16px;z-index:-1;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.4);
}

/* ---------- Radar ---------- */
#radarscreen{padding:0;}
#map{position:absolute;inset:0;background:#0a1120;z-index:1;}
.radar-wrap{position:absolute;inset:0;top:0;bottom:0;z-index:1;}
.radar-top{
  position:absolute;top:0;left:0;right:0;z-index:400;padding:10px 12px 0;
  display:flex;flex-direction:column;gap:8px;pointer-events:none;
}
.radar-top>*{pointer-events:auto;}
.chip-row{display:flex;gap:6px;overflow-x:auto;}
.chip{
  flex:0 0 auto;background:rgba(10,15,25,.8);backdrop-filter:blur(10px);
  border:1px solid var(--border);color:var(--dim);padding:7px 12px;border-radius:100px;
  font-size:12.5px;font-weight:600;cursor:pointer;display:flex;align-items:center;gap:5px;white-space:nowrap;
}
.chip.active{background:var(--cool);color:#04302c;border-color:var(--cool);}
.chip.homechip{background:rgba(255,255,255,.16);color:#fff;}
.chip svg{width:13px;height:13px;}

.radar-bottom{
  position:absolute;bottom:0;left:0;right:0;z-index:400;
  padding:10px 12px calc(var(--tabbar-h) + 22px + env(safe-area-inset-bottom));
  background:linear-gradient(0deg,rgba(6,10,18,.92),rgba(6,10,18,.55) 70%,transparent);
}
.legend{display:flex;align-items:center;gap:6px;margin-bottom:8px;font-size:10.5px;color:var(--dim);}
.legend .swatches{display:flex;flex:1;height:6px;border-radius:4px;overflow:hidden;}
.legend .swatches div{flex:1;}
.radar-panel-head{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:12px;
  margin-bottom:8px;
  color:#fff;
}
.radar-panel-head b{
  display:block;
  font-size:13px;
  letter-spacing:.01em;
}
.radar-panel-head span{
  display:block;
  color:rgba(233,238,251,.72);
  font-size:11px;
  margin-top:2px;
}
.radar-now-badge{
  display:none!important;
  flex:0 0 auto;
  align-items:center;
  justify-content:center;
  min-width:38px;
  min-height:24px;
  border-radius:999px;
  padding:3px 9px;
  background:rgba(53,208,196,.22);
  border:1px solid rgba(143,231,255,.5);
  color:#baf8ff!important;
  font-size:11px!important;
