  box-shadow:inset 0 1px 0 rgba(255,255,255,.22),0 8px 20px rgba(0,0,0,.16);
}
.radar-now-badge.show{display:flex!important;}
.timeline-row{display:flex;align-items:center;gap:8px;}
.playbtn{
  width:36px;height:36px;border-radius:50%;background:var(--cool);border:none;color:#04302c;
  display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;
}
.playbtn svg{width:16px;height:16px;}
.timeline{flex:1;display:flex;gap:2px;overflow-x:auto;align-items:flex-end;height:34px;}
.tframe{
  flex:0 0 5px;background:var(--elev2);border-radius:2px;cursor:pointer;transition:background .15s;
  align-self:flex-end;
}
.tframe.nowcast{background:repeating-linear-gradient(45deg,var(--elev2),var(--elev2) 2px,transparent 2px,transparent 4px);}
.tframe.active{background:var(--cool) !important;}
.timelabel{font-size:11px;color:var(--dim);width:64px;text-align:right;font-family:'JetBrains Mono',monospace;flex-shrink:0;}
.radar-frame-slider{
  width:100%;
  margin:8px 0 2px;
  accent-color:var(--cool);
}
.radar-axis{
  display:flex;
  justify-content:space-between;
  color:rgba(233,238,251,.58);
  font-size:10px;
