}
.hourlychart .hbar-col{
  flex:0 0 auto;width:26px;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;gap:4px;
}
.hourlychart .hbar-track{flex:1;display:flex;align-items:flex-end;width:10px;}
.hourlychart .hbar{
  width:100%;border-radius:3px 3px 0 0;background:linear-gradient(180deg,var(--cool),#1c8f86);min-height:2px;
}
