  overflow-y:auto;
  overflow-x:hidden;
  overscroll-behavior-y:contain;
  -webkit-overflow-scrolling:touch;
  touch-action:pan-y;
  padding:16px 16px calc(20px + env(safe-area-inset-bottom));
  visibility:hidden;
  pointer-events:none;
}
.panelsheet.show{transform:translateY(0);visibility:visible;pointer-events:auto;}
