.slider-block input[type=range]{width:100%;accent-color:var(--cape);}

.fav-chip{
  display:inline-flex;align-items:center;gap:6px;background:rgba(255,255,255,.06);border:1px solid var(--border);
  padding:6px 10px;border-radius:100px;font-size:12.5px;margin:0 6px 6px 0;cursor:pointer;
}
.fav-chip .x{color:var(--dim2);font-size:11px;}
.fav-chip.active{border-color:var(--cool);color:var(--cool);}

table.hourtable{width:100%;border-collapse:collapse;font-size:12.5px;}
table.hourtable th{
  text-align:right;color:var(--dim);font-weight:600;font-size:10.5px;text-transform:uppercase;
  padding:6px 4px;border-bottom:1px solid var(--border);position:sticky;top:0;background:var(--elev);
}
table.hourtable th:first-child,table.hourtable td:first-child{text-align:left;}
table.hourtable td{padding:7px 4px;text-align:right;border-bottom:1px solid var(--border);font-family:'JetBrains Mono',monospace;}
table.hourtable tr.hit{background:rgba(245,165,36,.1);}
table.hourtable tr.hit td:first-child{color:var(--storm);font-weight:600;}
.tablewrap{max-height:340px;overflow-y:auto;border-radius:12px;}

.safety-note{
  font-size:11.5px;color:var(--dim);background:rgba(239,75,95,.08);border:1px solid rgba(239,75,95,.25);
  border-radius:12px;padding:10px 12px;line-height:1.5;margin-top:12px;
}
.safety-note b{color:var(--severe);}

.empty-state{text-align:center;padding:40px 20px;color:var(--dim);}
.empty-state svg{width:38px;height:38px;margin-bottom:10px;opacity:.6;}

.loader{
  position:absolute;inset:0;display:flex;align-items:center;justify-content:center;
  background:var(--bg);z-index:2;flex-direction:column;gap:10px;
}
.loader.hide{display:none;}
.spinner{
  width:46px;
  height:46px;
  border-radius:14px;
  border:none;
  background:url("./icons/icon-96.png") center/contain no-repeat;
  box-shadow:0 12px 32px rgba(0,0,0,.20);
  animation:loaderLogoPulse 1.2s ease-in-out infinite;
}
@keyframes spin{to{transform:rotate(360deg);}}
@keyframes loaderLogoPulse{0%,100%{transform:scale(1);opacity:.86;}50%{transform:scale(1.04);opacity:1;}}
.loader span{font-size:12.5px;color:var(--dim);}

.toast{
  position:absolute;bottom:76px;left:50%;transform:translateX(-50%);
  background:var(--elev2);color:var(--text);padding:9px 16px;border-radius:100px;font-size:12.5px;
  z-index:900;opacity:0;transition:opacity .25s;pointer-events:none;box-shadow:0 10px 30px rgba(0,0,0,.4);
}
.toast.show{opacity:1;}

.section-h{font-size:20px;font-weight:600;margin:4px 0 12px;}
.subtle{color:var(--dim);font-size:13px;line-height:1.5;}
.headerbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;}
.smallbtn{background:rgba(20,30,50,.35);border:1px solid rgba(255,255,255,.16);color:rgba(233,238,251,.85);border-radius:9px;padding:6px 10px;font-size:11.5px;font-weight:600;cursor:pointer;}

