/* ---------------- TV mode: single stable layout ---------------- */
#tvscreen{
  position:fixed;
  inset:0;
  z-index:3000;
  width:100vw;
  height:100vh;
  height:100dvh;
  min-height:100vh;
  min-height:100dvh;
  box-sizing:border-box;
  display:none;
  grid-template-rows:auto minmax(0,1fr);
  gap:clamp(12px,1.6vh,20px);
  padding:clamp(16px,2.2vh,30px) clamp(30px,4.4vw,68px) clamp(18px,2.6vh,34px);
  overflow:hidden;
  color:#fff;
  background:transparent;
  isolation:isolate;
}
#tvscreen.active{display:grid;}
#tvscreen::before{
  content:"";
  position:absolute;
  inset:0;
  z-index:-2;
  background-image:var(--tv-weather-photo,var(--weather-photo));
  background-size:cover;
  background-position:center center;
  background-repeat:no-repeat;
  transform:scale(1.01);
}
#tvscreen::after{
  content:"";
  position:absolute;
  inset:0;
  z-index:-1;
  pointer-events:none;
  background:
    linear-gradient(180deg,rgba(6,14,28,.20) 0%,rgba(6,14,28,.12) 24%,rgba(6,14,28,.28) 100%),
    radial-gradient(circle at 12% 10%, rgba(255,255,255,.10), transparent 28%);
}
#tvscreen > *{
  position:relative;
  z-index:1;
}
.tv-top{
  min-width:0;
