/* ---------- Final weather mood override ---------- */
#weatherBG .wbg-sun{display:block!important;}
#weatherBG .wbg-clouds,
#weatherBG .wbg-rain,
#weatherBG .wbg-snow,
#weatherBG .wbg-lightning,
#weatherBG .wbg-moon{display:none!important;}
#weatherBG.sunny:not(.night) .wbg-sky{
  background:
    radial-gradient(circle at 17% 8%, rgba(255,239,188,.88) 0%, rgba(255,218,123,.34) 18%, transparent 39%),
    radial-gradient(circle at 78% 20%, rgba(110,205,255,.34) 0%, transparent 36%),
    linear-gradient(165deg,#66b9ff 0%,#2f83da 45%,#14549a 78%,#09264e 100%)!important;
}
#weatherBG.cloudy:not(.night) .wbg-sky{
  background:
    radial-gradient(circle at 22% 6%, rgba(230,236,244,.34), transparent 30%),
    linear-gradient(165deg,#8292a5 0%,#5f7189 44%,#2d3d55 76%,#111a2b 100%)!important;
}
#weatherBG.rainy:not(.night) .wbg-sky,
#weatherBG.stormy:not(.night) .wbg-sky{
  background:
    radial-gradient(circle at 18% 0%, rgba(210,220,232,.22), transparent 30%),
    linear-gradient(165deg,#6d7c8d 0%,#4c5b6f 45%,#263246 78%,#0d1422 100%)!important;
}
#weatherBG.snowy:not(.night) .wbg-sky{
  background:
    radial-gradient(circle at 22% 5%, rgba(238,246,255,.34), transparent 32%),
    linear-gradient(165deg,#a3b3c7 0%,#71859f 48%,#304059 82%,#11192a 100%)!important;
}
#weatherBG.sunny:not(.night) .wbg-sun{opacity:.92!important;}
#weatherBG.cloudy:not(.night) .wbg-sun{opacity:.16!important;}
#weatherBG.rainy:not(.night) .wbg-sun,
#weatherBG.stormy:not(.night) .wbg-sun,
#weatherBG.snowy:not(.night) .wbg-sun,
#weatherBG.night .wbg-sun{opacity:0!important;}

/* TV mode now uses the same photo background as the main app. */
body:has(#weatherBG.sunny:not(.night)) #tvscreen,
body:has(#weatherBG.cloudy:not(.night)) #tvscreen,
body:has(#weatherBG.rainy:not(.night)) #tvscreen,
body:has(#weatherBG.stormy:not(.night)) #tvscreen,
body:has(#weatherBG.snowy:not(.night)) #tvscreen,
body:has(#weatherBG.night) #tvscreen{
  background:transparent;
}

