/* ---------- Final premium mobile tabbar: Apple-like Liquid Glass ---------- */
:root{
  --tabbar-h:74px;
}
.tabbar{
  position:fixed!important;
  left:50%!important;
  right:auto!important;
  top:auto!important;
  bottom:calc(5px + env(safe-area-inset-bottom))!important;
  width:min(620px, calc(100vw - max(24px, env(safe-area-inset-left)) - max(24px, env(safe-area-inset-right))))!important;
  min-height:64px!important;
  display:flex!important;
  align-items:center!important;
  justify-content:space-between!important;
  gap:5px!important;
  padding:6px!important;
  box-sizing:border-box!important;
  overflow:hidden!important;
  border-radius:999px!important;
  clip-path:inset(0 round 999px)!important;
  contain:layout paint style!important;
  background-clip:padding-box!important;
  isolation:isolate!important;
  background:
    linear-gradient(180deg,rgba(255,255,255,.07),rgba(255,255,255,.025) 46%,rgba(255,255,255,.045)),
    radial-gradient(circle at 20% 0%,rgba(255,255,255,.08),transparent 36%),
    rgba(255,255,255,.035)!important;
  border:1px solid rgba(255,255,255,.20)!important;
  box-shadow:
    0 20px 52px rgba(0,8,22,.30),
    0 5px 18px rgba(0,0,0,.16),
    inset 0 1px 0 rgba(255,255,255,.44),
    inset 0 -1px 0 rgba(255,255,255,.12),
    inset 0 0 0 1px rgba(255,255,255,.08)!important;
  backdrop-filter:blur(16px) saturate(145%) brightness(1.02)!important;
  -webkit-backdrop-filter:blur(16px) saturate(145%) brightness(1.02)!important;
  transform:translateX(-50%) translateZ(0)!important;
  transition:transform .28s cubic-bezier(.2,.8,.2,1), box-shadow .28s ease, background .28s ease!important;
}
.tabbar::before{
  content:''!important;
  position:absolute!important;
  inset:1px 1px auto!important;
  height:52%!important;
  border-radius:999px!important;
  pointer-events:none!important;
  background:linear-gradient(180deg,rgba(255,255,255,.12),rgba(255,255,255,.015))!important;
  opacity:.92!important;
  z-index:0!important;
}
.tabbar::after{
  content:''!important;
  position:absolute!important;
  top:-45%!important;
  left:-42%!important;
  width:42%!important;
  height:190%!important;
  border-radius:999px!important;
  pointer-events:none!important;
  background:linear-gradient(105deg,transparent 0%,rgba(255,255,255,.02) 22%,rgba(255,255,255,.28) 48%,rgba(255,255,255,.03) 72%,transparent 100%)!important;
  transform:rotate(8deg)!important;
  animation:tabbarGlassSheen 9s ease-in-out infinite!important;
  z-index:0!important;
}
.tabbtn{
  flex:1 1 0!important;
  min-width:0!important;
  width:auto!important;
  min-height:52px!important;
  position:relative!important;
  z-index:1!important;
  display:flex!important;
  flex-direction:column!important;
  align-items:center!important;
  justify-content:center!important;
  gap:4px!important;
  padding:5px 4px!important;
  border:0!important;
  border-radius:999px!important;
  background:transparent!important;
  color:rgba(246,250,255,.82)!important;
  font-size:10.5px!important;
  font-weight:700!important;
  line-height:1!important;
  letter-spacing:0!important;
  text-shadow:0 1px 8px rgba(0,0,0,.34)!important;
  -webkit-tap-highlight-color:transparent!important;
  transition:color .22s ease, transform .18s ease, background .22s ease!important;
}
.tabbtn svg{
  width:22px!important;
  height:22px!important;
  stroke-width:2.2!important;
  filter:drop-shadow(0 1px 6px rgba(0,0,0,.22))!important;
  transition:transform .18s ease, filter .18s ease!important;
}
.tabbtn.active{
  color:#fff!important;
}
.tabbtn.active svg{
  transform:scale(1.04)!important;
  filter:drop-shadow(0 1px 1px rgba(255,255,255,.34))!important;
}
.tabbtn.active::before{
  content:''!important;
  position:absolute!important;
  inset:0!important;
  z-index:-1!important;
  border-radius:999px!important;
  background:
    linear-gradient(180deg,rgba(255,255,255,.12),rgba(255,255,255,.04) 55%,rgba(255,255,255,.07)),
    rgba(255,255,255,.06)!important;
  border:1px solid rgba(255,255,255,.22)!important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.45),
    inset 0 -1px 0 rgba(255,255,255,.10),
    0 8px 22px rgba(0,0,0,.15)!important;
}
.tabbtn:active{
  transform:scale(.965)!important;
}
@keyframes tabbarGlassSheen{
  0%,24%{left:-46%;opacity:0;}
  36%{opacity:.62;}
  58%{left:104%;opacity:.18;}
  100%{left:104%;opacity:0;}
}
@supports not ((backdrop-filter:blur(1px)) or (-webkit-backdrop-filter:blur(1px))){
  .tabbar{
    background:rgba(28,45,74,.86)!important;
    border-color:rgba(255,255,255,.22)!important;
