/* ---------- Near-real weather backgrounds ---------- */
#weatherBG{
  background:#142235!important;
}
#weatherBG::before{
  content:''!important;
  position:absolute!important;
  inset:0!important;
  z-index:0!important;
  pointer-events:none!important;
  opacity:0!important;
  background-size:cover!important;
  background-position:center!important;
  transform:scale(1.03)!important;
  transition:opacity .75s ease, filter .75s ease!important;
}
#weatherBG .wbg-sky{
  overflow:hidden!important;
  z-index:1!important;
}
#weatherBG .wbg-sky::before,
#weatherBG .wbg-sky::after{
  content:''!important;
  position:absolute!important;
  inset:-18% -22%!important;
  pointer-events:none!important;
  opacity:.78!important;
  transform:translateZ(0)!important;
}
#weatherBG .wbg-sky::before{
  background:
    radial-gradient(ellipse at 18% 18%, rgba(255,255,255,.78) 0 9%, rgba(214,225,235,.54) 16%, transparent 31%),
    radial-gradient(ellipse at 52% 20%, rgba(242,247,252,.72) 0 12%, rgba(153,174,192,.38) 24%, transparent 41%),
