/* ---------- Photorealistic condition backgrounds ---------- */
#weatherBG.photo-weather-bg{
  background:#0b172b;
}
#weatherBG.photo-weather-bg::before{
  content:"";
  position:absolute;
  inset:0;
  z-index:-2;
  background-image:var(--weather-photo);
  background-size:cover;
  background-position:center center;
  background-repeat:no-repeat;
  transform:scale(1.015);
  transition:background-image .7s ease, opacity .7s ease;
}
#weatherBG.photo-weather-bg::after{
  content:"";
  position:absolute;
  inset:0;
  z-index:20;
  pointer-events:none;
  background:linear-gradient(180deg,rgba(8,19,36,.08) 0%,rgba(8,19,36,.04) 42%,rgba(4,12,24,.30) 100%);
}
