:root{
  --wf-card-primary:rgba(78,104,132,.44);
  --wf-card-secondary:rgba(88,112,138,.36);
  --wf-card-soft:rgba(98,121,146,.30);
  --wf-card-border:rgba(230,241,255,.22);
  --wf-text:#f8fbff;
  --wf-text-secondary:rgba(236,244,255,.82);
  --wf-card-blur:9px;
  --wf-card-shadow:0 8px 22px rgba(8,20,38,.13);
}

.card,.detail-card,.weather-summary-card,.rain-now-card,.compact-forecast-card,
.sea-mode-card,.seaspark-panel,.travel-weather-card,.air-quality-card,
.community-post,.profile-weather-card,.profile-stat-card,.profile-pro-card,
.profile-menu-list,.profile-edit-panel,.profile-favorites,.account-actions,
.chart-card,.graph-card,.wf-data-status{
  background:linear-gradient(145deg,rgba(118,143,168,.46),rgba(72,101,132,.38))!important;
  border:1px solid var(--wf-card-border)!important;
  color:var(--wf-text)!important;
  box-shadow:var(--wf-card-shadow)!important;
  -webkit-backdrop-filter:blur(var(--wf-card-blur)) saturate(118%)!important;
  backdrop-filter:blur(var(--wf-card-blur)) saturate(118%)!important;
}

.detail-card,.hour-item,.hour-card,.daily-row,.daily-row-compact,
.sea-compact-grid>div,.sea-score-grid>div,.travel-result-card,
.community-observation-main,.seaspark-shared-grid>span,.rain-now-facts>span,
