  box-shadow:inset 0 1px 0 rgba(255,255,255,.08)!important;
}
.sea-mode-card.sea-mode-compact .sea-advice-compact b{
  flex:0 0 auto;
  font-size:12px!important;
  line-height:1.4!important;
}
.sea-mode-card.sea-mode-compact .sea-advice-compact span{
  min-width:0;
  font-size:12px!important;
  line-height:1.45!important;
}

@media(max-width:430px){
  .sea-mode-card.sea-mode-compact .sea-score-grid{gap:10px!important;}
  .sea-mode-card.sea-mode-compact .sea-score-grid>div{padding:13px!important;}
