  .sea-mode-card.sea-mode-compact .sea-compact-icon{width:34px;height:34px;border-radius:12px;}
  .sea-mode-card.sea-mode-compact .sea-compact-icon svg{width:19px!important;height:19px!important;}
  .sea-mode-card.sea-mode-compact .sea-compact-label{font-size:11.5px!important;}
  .sea-mode-card.sea-mode-compact .sea-compact-value{font-size:15px!important;}
  .sea-mode-card.sea-mode-compact .sea-compact-detail{font-size:10.5px!important;}
}
@media(max-width:350px){
  .sea-mode-card.sea-mode-compact .sea-compact-grid{
    grid-template-columns:1fr!important;
