  .sea-mode-card.sea-mode-compact .sea-compact-item:last-child:nth-child(odd){grid-column:auto!important;}
  .sea-mode-card.sea-mode-compact .sea-compact-value{font-size:16px!important;}
}


/* ---------- Air Quality v1: compact extras + verbeterde Pollenkaart ---------- */
#home .air-quality-card .aq-grid{align-items:stretch;}
#home .air-quality-card .aq-secondary,
#home .air-quality-card .pollen-card{grid-column:1 / -1!important;}
#home .air-quality-card .aq-secondary{
  display:grid!important;
  grid-template-columns:minmax(130px,.65fr) minmax(0,1.35fr)!important;
  align-items:center!important;
  gap:12px!important;
}
#home .air-quality-card .aq-secondary-title{min-width:0;}
#home .air-quality-card .aq-secondary-values{
  display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;min-width:0;
}
#home .air-quality-card .aq-mini{
  position:relative;min-width:0;padding:8px 9px 10px;border-radius:13px;
  background:rgba(255,255,255,.045);border:1px solid rgba(255,255,255,.08);
}
#home .air-quality-card .aq-mini>span{display:block!important;font-size:12px!important;font-weight:850!important;color:rgba(238,247,255,.76)!important;}
#home .air-quality-card .aq-mini>b{display:block;margin-top:3px;color:#fff;font-size:13px;line-height:1.25;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
#home .air-quality-card .aq-mini>small{display:block;margin-top:2px;color:rgba(232,240,255,.62);font-size:10px;font-weight:800;}
#home .air-quality-card .aq-mini>i{display:block;height:4px;margin-top:7px;overflow:hidden;border-radius:999px;background:rgba(255,255,255,.10);}
#home .air-quality-card .aq-mini>i>em{display:block;height:100%;border-radius:999px;background:linear-gradient(90deg,#35d0c4,#75e28a,#f5c451,#f59e0b,#ef3c78);}
#home .air-quality-card .pollen-card{display:block!important;padding:13px 14px!important;}
#home .air-quality-card .pollen-card-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:11px;}
#home .air-quality-card .pollen-card-head>span{min-width:0;}
#home .air-quality-card .pollen-card-head>strong{flex:0 0 auto;padding:5px 9px;border-radius:999px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.10);font-size:11px!important;line-height:1;}
#home .air-quality-card .pollen-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px 8px;}
#home .air-quality-card .pollen-item{min-width:0;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:4px 8px;align-items:center;padding:7px 8px;border-radius:12px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.07);}
#home .air-quality-card .pollen-item>span{display:block!important;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:rgba(238,247,255,.78)!important;font-size:11px!important;font-weight:800!important;}
#home .air-quality-card .pollen-item>b{color:#fff;font-size:12px;font-weight:850;white-space:nowrap;}
#home .air-quality-card .pollen-item>i{grid-column:1 / -1;display:block;height:3px;overflow:hidden;border-radius:999px;background:rgba(255,255,255,.10);}
#home .air-quality-card .pollen-item>i>em{display:block;height:100%;border-radius:999px;background:linear-gradient(90deg,#35d0c4,#75e28a,#f5c451,#f59e0b,#ef3c78);}
@media (max-width:620px){
  #home .air-quality-card .aq-secondary{grid-template-columns:1fr!important;}
  #home .air-quality-card .pollen-list{grid-template-columns:repeat(2,minmax(0,1fr));}
}
@media (max-width:370px){
  #home .air-quality-card .aq-grid{grid-template-columns:1fr!important;}
  #home .air-quality-card .aq-secondary,#home .air-quality-card .pollen-card{grid-column:1!important;}
  #home .air-quality-card .pollen-list{grid-template-columns:1fr 1fr;}
}


/* ---------- Community photo reliability v1 ---------- */
#communityscreen [data-community-media]{
  position:relative;
  overflow:hidden;
  background:
    radial-gradient(circle at 50% 32%,rgba(75,184,255,.10),transparent 42%),
    linear-gradient(145deg,rgba(10,29,54,.96),rgba(5,17,33,.98));
}
#communityscreen .community-photo-fallback{
  position:absolute;
  inset:0;
  z-index:1;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:6px;
  padding:24px;
  text-align:center;
  color:rgba(230,243,255,.74);
  pointer-events:none;
  opacity:1;
  transition:opacity .22s ease;
}
#communityscreen .community-photo-fallback svg{
  width:38px;
  height:38px;
  fill:none;
  stroke:#7ddfff;
  stroke-width:1.6;
  stroke-linecap:round;
  stroke-linejoin:round;
  filter:drop-shadow(0 0 13px rgba(71,207,255,.26));
}
#communityscreen .community-photo-fallback strong{
  color:#eef8ff;
  font-size:14px;
  font-weight:800;
}
#communityscreen .community-photo-fallback span{
  color:rgba(224,239,255,.57);
  font-size:12px;
}
#communityscreen [data-community-media] img[data-community-photo]{
  position:relative;
  z-index:2;
  opacity:0;
  transition:opacity .24s ease;
}
#communityscreen [data-community-media].is-loaded img[data-community-photo]{opacity:1}
#communityscreen [data-community-media].is-loaded .community-photo-fallback{opacity:0}
#communityscreen [data-community-media].is-recovering .community-photo-fallback svg{
  animation:communityPhotoPulse 1.25s ease-in-out infinite;
}
#communityscreen [data-community-media].is-failed img[data-community-photo]{
  display:none!important;
}
#communityscreen [data-community-media].is-failed .community-photo-fallback{
  opacity:1;
  background:linear-gradient(145deg,rgba(15,37,65,.94),rgba(6,20,39,.98));
}
@keyframes communityPhotoPulse{
  0%,100%{opacity:.55;transform:scale(.96)}
  50%{opacity:1;transform:scale(1.04)}
}
.community-map-photo-wrap{
  width:150px;
  min-height:105px;
  margin-top:6px;
  border-radius:10px;
  overflow:hidden;
  position:relative;
  background:#0a1629;
}
.community-map-photo{
  width:150px;
  height:105px;
  display:block;
  object-fit:cover;
}
.community-map-photo-wrap .community-photo-fallback{
  padding:10px;
  gap:3px;
}
.community-map-photo-wrap .community-photo-fallback svg{width:24px;height:24px}
.community-map-photo-wrap .community-photo-fallback strong{font-size:11px}
.community-map-photo-wrap .community-photo-fallback span{display:none}
@media (prefers-reduced-motion:reduce){
  #communityscreen [data-community-media] img[data-community-photo],
  #communityscreen .community-photo-fallback{transition:none!important}
  #communityscreen [data-community-media].is-recovering .community-photo-fallback svg{animation:none!important}
}


/* TV assets v3 — HD main weather icon + graceful detail-icon fallback */
#tvscreen.active .tv-current .tv-icon img{
  image-rendering:auto!important;
  object-fit:contain!important;
  filter:none!important;
  transform:translateZ(0);
  backface-visibility:hidden;
}
#tvscreen .tv-feature-icon-fallback{
  display:flex!important;
  align-items:center;
  justify-content:center;
  color:#8fe9ff;
}
#tvscreen .tv-feature-icon-fallback svg{
  width:76%!important;
  height:76%!important;
  display:block;
}


